        for id, g in pairs(Gears.Directory) do
            if type(g) == "table" and g.IndexBatTier == nil and id ~= "Bat" then
                out[#out + 1] = id
            end
        end
    end
    table.sort(out)
    if #out == 0 then out = { "BeeLauncher" } end
    return out
end
